import React, { useState } from "react";
import { useHistory } from "react-router-dom";
import "./adminPortfolio.css";

const AdminPortfolio = () => {
  const history = useHistory();
  const [showSettings, setShowSettings] = useState(false);

  const handleSettingsClick = () => {
    setShowSettings(!showSettings);
  };

  const handleOptionClick = (option) => {
    setShowSettings(false); // Hide the menu after an option is selected
    switch (option) {
      case "theme":
        // Handle theme change
        alert("Change Theme");
        break;
      case "signOut":
        // Handle sign out
        alert("Sign Out");
        break;
      case "previousOrders":
        // Navigate to previous orders
        history.push("/previous-orders");
        break;
      default:
        break;
    }
  };

  return (
    <div>
      {/* Header */}
      <header>
        <button id="back-button" onClick={() => history.goBack()}>Back</button>
        <h1>Admin Portfolio</h1>
        <button id="settings" onClick={handleSettingsClick}>Settings</button>
        {showSettings && (
          <div className="settings-dropdown">
            <ul>
              <li onClick={() => handleOptionClick("theme")}>Change Theme</li>
              <li onClick={() => handleOptionClick("signOut")}>Sign Out</li>
              <li onClick={() => handleOptionClick("previousOrders")}>Previous Orders</li>
            </ul>
          </div>
        )}
      </header>

      {/* Main Content */}
      <main>
        {/* Your existing content here */}
      </main>
    </div>
  );
};

export default AdminPortfolio;
